<!--
  The Kopffeld-Check as a page — OBO-156 part 4.

  Mockup: "Ergebnis als Seite zum Zeigen, Drucken oder Mailen" and "Auch aus
  dem Dashboard für mehrere Belege auf einmal". One document comes in by path
  (`/header-field-check/:docId`, from the dialog), several by query
  (`/header-field-check?ids=a,b`, from the dashboard selection).

  The report body is HeaderFieldReportView, the same component the dialog
  shows — this page only adds the frame around it: a card per document, the
  toolbar, and a print layout with one document per sheet.
-->
<template>
  <div class="hfc-page mx-auto flex w-full max-w-6xl flex-col gap-4 p-4">
    <div
      class="hfc-page__toolbar flex flex-wrap items-center justify-end gap-2"
      data-test="hfc-page-toolbar"
    >
      <f-btn appearance="secondary" data-test="hfc-page-print" @click="printPage">
        <span class="flex items-center gap-2">
          <Icon icon="mdi:printer-outline" class="size-4" />
          <span>{{ $t('header_field_check_print') }}</span>
        </span>
      </f-btn>
      <f-btn appearance="secondary" data-test="hfc-page-copy-link" @click="copyLink">
        <span class="flex items-center gap-2">
          <Icon icon="mdi:link-variant" class="size-4" />
          <span>{{ $t('header_field_check_copy_link') }}</span>
        </span>
      </f-btn>
      <!-- `href` falls through f-btn to QBtn, which renders it as a link: the
           mail client opens from a real anchor, not from a script. -->
      <f-btn appearance="secondary" data-test="hfc-page-mail" :href="mailtoHref">
        <span class="flex items-center gap-2">
          <Icon icon="mdi:email-outline" class="size-4" />
          <span>{{ $t('header_field_check_send_mail') }}</span>
        </span>
      </f-btn>
    </div>

    <div
      v-if="tooMany"
      data-test="hfc-page-too-many"
      class="hfc-page__notice rounded-md border border-warning/40 bg-warning/10 p-3 text-sm text-foreground"
    >
      {{ $t('header_field_check_page_too_many', { max: maxDocs }) }}
    </div>

    <div
      v-if="!entries.length"
      data-test="hfc-page-empty"
      class="rounded-md border border-destructive/40 bg-destructive/5 p-4 text-sm text-destructive"
    >
      {{ $t('header_field_check_load_failed') }}
    </div>

    <section
      v-for="entry in entries"
      :key="entry.id"
      data-test="hfc-page-doc"
      class="hfc-page__doc rounded-lg border border-border bg-card p-4 shadow-sm"
    >
      <div
        v-if="entry.status === 'loading'"
        class="flex items-center justify-center gap-2 py-10 text-sm text-muted-foreground"
      >
        <Icon icon="mdi:loading" class="size-5 animate-spin" />
        <span>{{ $t('loading') }}</span>
      </div>

      <div
        v-else-if="entry.status === 'error'"
        data-test="hfc-page-doc-error"
        class="flex flex-col gap-1 rounded-md border border-destructive/40 bg-destructive/5 p-4 text-sm text-destructive"
      >
        <span>{{ $t('header_field_check_page_doc_failed') }}</span>
        <span class="font-mono text-xs text-muted-foreground">{{ entry.id }}</span>
      </div>

      <HeaderFieldReportView v-else-if="entry.report" :report="entry.report" />
    </section>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { copyToClipboard } from 'quasar';
import { Icon } from '@iconify/vue';
import HeaderFieldReportView from 'src/components/document/HeaderFieldReportView.vue';
import HeaderFieldReportApiService from 'src/services/document/HeaderFieldReportApiService';
import type { HeaderFieldReport } from 'src/types/headerFieldReport';
import { notify } from 'src/components/notifications/notify';
import { logger } from 'src/utils/logger';
import {
  HEADER_FIELD_CHECK_MAX_DOCS,
  buildReportMailto,
  parseReportDocIds,
} from 'src/utils/header-field-check-view';

interface ReportEntry {
  id: string;
  status: 'loading' | 'ready' | 'error';
  report: HeaderFieldReport | null;
}

export default defineComponent({
  name: 'HeaderFieldCheckPage',
  components: { HeaderFieldReportView, Icon },
  data() {
    return {
      entries: [] as ReportEntry[],
      /** Which load may still write: a route change starts a new one. */
      loadGeneration: 0,
      maxDocs: HEADER_FIELD_CHECK_MAX_DOCS,
    };
  },
  computed: {
    /** Every id the URL names, before the cap. */
    requestedIds(): string[] {
      const fromPath = this.$route?.params?.docId;
      const raw = fromPath ? fromPath : this.$route?.query?.ids;
      return parseReportDocIds(raw, Infinity);
    },
    docIds(): string[] {
      return this.requestedIds.slice(0, HEADER_FIELD_CHECK_MAX_DOCS);
    },
    docIdsKey(): string {
      return this.docIds.join(',');
    },
    tooMany(): boolean {
      return this.requestedIds.length > HEADER_FIELD_CHECK_MAX_DOCS;
    },
    mailtoHref(): string {
      // "for 1 documents" is what the plural key says about one document.
      const subject =
        this.docIds.length === 1
          ? this.$t('header_field_check_page_mail_subject_one')
          : this.$t('header_field_check_mail_subject', { count: this.docIds.length });
      return buildReportMailto(window.location.href, subject);
    },
  },
  watch: {
    docIdsKey: {
      handler() {
        void this.loadReports();
      },
      immediate: true,
    },
  },
  methods: {
    /**
     * One report after the other, each with its own state.
     *
     * Sequential on purpose: twenty parallel requests from one tab compete
     * with the dashboard the user just came from. A document that fails
     * shows its own error card and the loop moves on — one deleted or
     * inaccessible document must not blank a page of nineteen good ones.
     */
    async loadReports() {
      const generation = ++this.loadGeneration;
      this.entries = this.docIds.map((id) => ({ id, status: 'loading', report: null }));
      const service = new HeaderFieldReportApiService({});
      for (const entry of this.entries) {
        try {
          const report = await service.getForDocument(entry.id);
          if (generation !== this.loadGeneration) return;
          entry.report = report;
          entry.status = 'ready';
        } catch (error) {
          if (generation !== this.loadGeneration) return;
          logger.warn('[HEADER-FIELD-CHECK] page report load failed', entry.id, error);
          entry.status = 'error';
        }
      }
    },
    printPage() {
      window.print();
    },
    async copyLink() {
      try {
        await copyToClipboard(window.location.href);
        notify.success(this.$t('header_field_check_link_copied'));
      } catch (error) {
        logger.warn('[HEADER-FIELD-CHECK] copy link failed', error);
        notify.error(this.$t('header_field_check_link_copy_failed'));
      }
    },
  },
});
</script>

